#!/bin/sh
# Copies files from the template byte for byte, called with sh: a cp whose source is outside
# the project directory is refused by the agent's permission, a sh <template>/copy.sh is not.
# It does not go into the plan and carries no version stamp.
# Usage:
#   sh <template>/copy.sh [--lang <language>] <plan folder>
#       status.sh, task.sh and map.sh under the same name, and _template.md as _template.md
#   sh <template>/copy.sh [--lang <language>] <template file> <destination>
#       a single file, by its name in the template folder (no slash)
# --lang: the file comes from <template>/<language>/ when that folder has it: the text
# (_template.md, idea.md…) and, in the package, the scripts of an English plan, which carry only
# the English table. The language follows the contract rule (pt-BR ignoring case or by base
# language, anything else English). Without --lang, pt-BR (the files at the root of the template).
# Creates the destination folder when it is missing. Exits 0 when it copied; 1, without
# copying anything, if some destination already exists; 2 on wrong usage or a template file
# that does not exist.
# The messages come out in the package language, which is not the --lang one.

language='en'
# >>> strings (area copy.): generated by tools/script-strings.sh from core/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='copy.usage	x-test:copy.usage
copy.notAName	x-test:copy.notAName {0}
copy.missing	x-test:copy.missing {0} {1}
copy.alreadyExists	x-test:copy.alreadyExists {0}
' ;;
  pt-BR) MSG_TABLE='copy.usage	Uso: sh copy.sh [--lang <língua>] <pasta do plano> | sh copy.sh [--lang <língua>] <arquivo do modelo> <destino>
copy.notAName	copy.sh: «{0}» não é um nome de arquivo da pasta do modelo
copy.missing	copy.sh: falta {0} no modelo ({1})
copy.alreadyExists	copy.sh: {0} já existe; nada foi copiado
' ;;
  *) MSG_TABLE='copy.usage	Usage: sh copy.sh [--lang <language>] <plan folder> | sh copy.sh [--lang <language>] <template file> <destination>
copy.notAName	copy.sh: "{0}" is not a file name in the template folder
copy.missing	copy.sh: {0} is missing from the template ({1})
copy.alreadyExists	copy.sh: {0} already exists; nothing was copied
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings

template=$(cd "$(dirname "$0")" && pwd) || exit 2

usage() { msg copy.usage >&2; exit 2; }

template_language=pt-BR
if [ "${1-}" = --lang ]; then
  if [ $# -lt 2 ] || [ -z "$2" ]; then usage; fi
  # The contract rule for a plan's language: pt-BR ignoring case or by base language, anything else English.
  case "$2" in
    [Pp][Tt]|[Pp][Tt]-*) template_language=pt-BR ;;
    *) template_language=en ;;
  esac
  shift 2
fi

case $# in
  1)
    [ -n "$1" ] || usage
    folder=$1
    set -- status.sh "$folder/status.sh" task.sh "$folder/task.sh" map.sh "$folder/map.sh" _template.md "$folder/_template.md"
    ;;
  2)
    if [ -z "$1" ] || [ -z "$2" ]; then usage; fi
    case "$1" in
      */*|.|..) msg copy.notAName "$1" >&2; exit 2 ;;
    esac
    ;;
  *) usage ;;
esac

# check everything before copying: either all are copied, or none
n=0
while [ $# -gt 0 ]; do
  [ -f "$template/$1" ] || { msg copy.missing "$1" "$template" >&2; exit 2; }
  if [ -e "$2" ] || [ -L "$2" ]; then
    msg copy.alreadyExists "$2" >&2
    exit 1
  fi
  n=$((n + 1))
  eval "src_$n=\$1 dest_$n=\$2"
  if [ "$template_language" != pt-BR ] && [ -f "$template/$template_language/$1" ]; then eval "src_$n=\$template_language/\$1"; fi
  shift 2
done

i=1
o="" d=""  # filled in by the eval below; declared here for shellcheck (SC2154)
while [ "$i" -le "$n" ]; do
  eval "o=\$src_$i d=\$dest_$i"
  mkdir -p "$(dirname "$d")" || exit 1
  cp "$template/$o" "$d" || exit 1
  i=$((i + 1))
done
